// ============================================================
// HELPER — resolve data from pipeline JSON or fallback to samples
// ============================================================

function useResolvedData() {
  const { data: pipelineData, loading, error } = useVizData();

  const resolved = {
    matches: pipelineData?.matches ?? SAMPLE_MATCHES,
    tropeDistribution: pipelineData?.tropeDistribution ?? SAMPLE_TROPE_DIST,
    timeline: pipelineData?.timeline ?? SAMPLE_TIMELINE,
    calibration: pipelineData?.calibration ?? SAMPLE_CALIBRATION,
    tropeNames: pipelineData?.metadata?.tropeNames ?? DEFAULT_TROPE_NAMES,
    tropeColors: pipelineData?.metadata?.tropeColors ?? DEFAULT_TROPE_COLORS,
    isLive: !!pipelineData,
    loading,
    model: pipelineData?.model ?? null,
    generatedAt: pipelineData?.generated_at ?? null,
    sovietCorpusSize: pipelineData?.soviet_corpus_size ?? null,
    modernCorpusSize: pipelineData?.modern_corpus_size ?? null,
  };

  return resolved;
}

// ============================================================
// SUB-COMPONENTS
// ============================================================

function ConfidenceBadge({ level }) {
  const s = { high: { bg: "#1a472a", bd: "#2ecc71", c: "#2ecc71" }, medium: { bg: "#4a3800", bd: "#f1c40f", c: "#f1c40f" }, low: { bg: "#4a1a1a", bd: "#e74c3c", c: "#e74c3c" } }[level] || { bg: "#333", bd: "#888", c: "#888" };
  return <span style={{ background: s.bg, border: `1px solid ${s.bd}`, color: s.c, padding: "2px 8px", borderRadius: 4, fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: 1 }}>{level}</span>;
}

function SimilarityBar({ score }) {
  const pct = Math.round(score * 100);
  const color = score >= 0.85 ? "#2ecc71" : score >= 0.70 ? "#f1c40f" : score >= 0.55 ? "#e67e22" : "#555";
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
      <div style={{ flex: 1, height: 6, background: "var(--bg-card-alt)", borderRadius: 3, overflow: "hidden" }}>
        <div style={{ width: `${pct}%`, height: "100%", background: color, borderRadius: 3, transition: "width 1s ease-out" }} />
      </div>
      <span style={{ fontSize: 13, fontWeight: 700, color, minWidth: 40, textAlign: "right" }}>{pct}%</span>
    </div>
  );
}

function ScoreDonut({ score, size = 44 }) {
  const pct = Math.round(score * 100);
  const color = score >= 0.70 ? "#2ecc71" : score >= 0.55 ? "#f1c40f" : "#e67e22";
  const inner = size - 8;
  return (
    <div style={{ width: size, height: size, borderRadius: "50%", background: `conic-gradient(${color} ${score * 360}deg, var(--bg-card-alt) 0deg)`, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ width: inner, height: inner, borderRadius: "50%", background: "var(--bg-card)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, fontWeight: 700, color: "var(--text-heading)" }}>
        {pct}%
      </div>
    </div>
  );
}

function TropeBadge({ trope, tropeNames, tropeColors }) {
  return (
    <span style={{
      background: (tropeColors[trope] || "#888") + "22",
      border: `1px solid ${(tropeColors[trope] || "#888")}55`,
      color: tropeColors[trope] || "#888",
      padding: "2px 8px", borderRadius: 4, fontSize: 10, fontWeight: 600,
    }}>
      {tropeNames[trope] || trope}
    </span>
  );
}

function matchExplanation(match, tropeNames) {
  const tropes = match.tropes || [];
  if (tropes.length === 0) return "Both texts use strikingly similar framing when discussing Zionism and Israel.";
  const names = tropes.map(t => tropeNames[t] || t).slice(0, 2);
  const tropeStr = names.join(" and ");
  const yearGap = (match.modernYear || 2024) - (match.sovietYear || 1970);
  return `Both texts employ the "${tropeStr}" framing — the same rhetorical strategy used ${yearGap} years apart.`;
}

