function SocialCard({ match, tropeNames, tropeColors, sovietCorpusSize, modernCorpusSize }) {
  const [format, setFormat] = useState("story");
  const [activeSlide, setActiveSlide] = useState(0);
  const [exporting, setExporting] = useState(false);
  const [customMessage, setCustomMessage] = useState("");
  const slideRef = useRef(null);

  const generateThreadText = () => {
    const similarity = match.cross_encoder_score || match.similarity || 0;
    const pct = Math.round(similarity * 100);
    const tropeName = match.tropes?.[0] ? (tropeNames[match.tropes[0]] || match.tropes[0]) : "";

    const firstTweet = customMessage
      ? `${customMessage}\n\nThese talking points were manufactured by the Soviet regime. Yet its propaganda lives on. Here's the proof 👇\n\n1/5`
      : `"Zionism is racism." "Israel is apartheid." "Calling it antisemitism silences Palestinians."\n\nThese talking points were manufactured by the Soviet regime — which killed 20 million of its own citizens.\n\nYet its propaganda lives on. Here's the proof 👇\n\n1/5`;

    return [
      firstTweet,
      `In ${match.sovietYear || "1970"}, Soviet propagandists wrote:\n\n"${match.sovietText}"\n\n— ${match.sovietSource}\n\n2/5`,
      `Now look at this from ${match.modernYear || "2023"}:\n\n"${match.modernText}"\n\n— ${match.modernSource || "Social Media"}\n\nSame argument. Decades later.\n\n3/5`,
      `This is the "${tropeName}" trope. Our ML engine detected ${pct}% semantic similarity.\n\n${match.echo_explanation || ""}\n\n4/5`,
      `"I've Seen This Before" uses NLP to map Soviet anti-Zionist propaganda to today's rhetoric.\n\n${sovietCorpusSize || "1,807"} Soviet passages. ${modernCorpusSize || "3,900"} modern texts. 9 propaganda tropes.\n\nThe language changed. The playbook didn't.\n\n#IveSeenThisBefore #Antisemitism\n\n5/5`,
    ];
  };

  const shareToX = () => {
    const tweets = generateThreadText();
    const text = tweets[0];
    const url = `https://x.com/intent/tweet?text=${encodeURIComponent(text)}`;
    window.open(url, "_blank", "noopener");
  };

  const copyThreadText = async () => {
    const tweets = generateThreadText();
    const full = tweets.join("\n\n---\n\n");
    try {
      await navigator.clipboard.writeText(full);
      alert("Thread text copied to clipboard! Paste each tweet into X.");
    } catch {
      // fallback
      const ta = document.createElement("textarea");
      ta.value = full;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
      alert("Thread text copied to clipboard!");
    }
  };

  const downloadStorySlide = async () => {
    if (!slideRef.current) return;
    setExporting(true);
    try {
      const dataUrl = await toPng(slideRef.current, {
        width: 1080,
        height: 1920,
        style: { transform: "scale(3)", transformOrigin: "top left" },
        pixelRatio: 1,
      });
      const link = document.createElement("a");
      link.download = `iveseenthisbefore-story-${activeSlide + 1}.png`;
      link.href = dataUrl;
      link.click();
    } catch (err) {
      console.error("Export failed:", err);
      alert("Export failed. Try again.");
    }
    setExporting(false);
  };

  const downloadAllSlides = async () => {
    setExporting(true);
    const slideComponents = [0, 1, 2, 3, 4];
    for (const idx of slideComponents) {
      setActiveSlide(idx);
      // Wait for React to re-render the slide
      await new Promise(r => setTimeout(r, 200));
      if (!slideRef.current) continue;
      try {
        const dataUrl = await toPng(slideRef.current, {
          width: 1080,
          height: 1920,
          style: { transform: "scale(3)", transformOrigin: "top left" },
          pixelRatio: 1,
        });
        const link = document.createElement("a");
        link.download = `iveseenthisbefore-story-${idx + 1}.png`;
        link.href = dataUrl;
        link.click();
        await new Promise(r => setTimeout(r, 300));
      } catch (err) {
        console.error(`Export slide ${idx + 1} failed:`, err);
      }
    }
    setExporting(false);
  };

  const canWebShare = typeof navigator !== "undefined" && !!navigator.share && !!navigator.canShare;

  const webShareSlide = async () => {
    if (!slideRef.current) return;
    setExporting(true);
    try {
      const dataUrl = await toPng(slideRef.current, {
        width: 1080, height: 1920,
        style: { transform: "scale(3)", transformOrigin: "top left" },
        pixelRatio: 1,
      });
      const res = await fetch(dataUrl);
      const blob = await res.blob();
      const file = new File([blob], `iveseenthisbefore-story-${activeSlide + 1}.png`, { type: "image/png" });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          title: "I've Seen This Before",
          text: "#IveSeenThisBefore — Soviet propaganda lives on in today's anti-Israel rhetoric",
          files: [file],
        });
      } else {
        // Fallback: share without file
        await navigator.share({
          title: "I've Seen This Before",
          text: "#IveSeenThisBefore — Soviet propaganda lives on in today's anti-Israel rhetoric\n\niveseenthisbefore.org",
        });
      }
    } catch (err) {
      if (err.name !== "AbortError") {
        console.error("Share failed:", err);
      }
    }
    setExporting(false);
  };

  const webShareThread = async () => {
    const tweets = generateThreadText();
    try {
      await navigator.share({
        title: "I've Seen This Before",
        text: tweets[0] + "\n\n" + tweets[1] + "\n\n" + tweets[2],
      });
    } catch (err) {
      if (err.name !== "AbortError") console.error("Share failed:", err);
    }
  };

  const slideLabels = ["Thesis", "Then", "Now", "Evidence", "CTA"];

  return (
    <div>
      {/* Custom message input */}
      <div style={{ maxWidth: 500, margin: "0 auto 20px" }}>
        <label style={{ display: "block", fontSize: 11, color: "var(--text-secondary)", marginBottom: 6, letterSpacing: 1, textTransform: "uppercase" }}>
          Your message (optional — appears on first slide / tweet)
        </label>
        <textarea
          value={customMessage}
          onChange={e => setCustomMessage(e.target.value)}
          placeholder='e.g. "I heard this on campus today and it sounded familiar..."'
          rows={3}
          style={{
            width: "100%", boxSizing: "border-box", background: "var(--bg-card)", border: "1px solid var(--border)",
            color: "var(--text-primary)", borderRadius: 8, padding: "10px 12px", fontSize: 14,
            fontFamily: "inherit", lineHeight: 1.5, resize: "vertical",
          }}
        />
        {customMessage && (
          <div style={{ fontSize: 11, color: "var(--text-muted)", marginTop: 4, textAlign: "right" }}>
            {customMessage.length} characters
          </div>
        )}
      </div>

      {/* Format selector */}
      <div style={{ display: "flex", gap: 8, justifyContent: "center", marginBottom: 24 }}>
        {[["story", "Instagram Story"], ["thread", "X Thread"]].map(([key, label]) => (
          <button key={key} onClick={() => setFormat(key)} style={{
            background: format === key ? "#c0392b" : "var(--bg-card-alt)",
            border: `1px solid ${format === key ? "#c0392b" : "var(--border)"}`,
            color: format === key ? "#fff" : "var(--text-secondary)",
            padding: "8px 20px", borderRadius: 8, cursor: "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit",
          }}>
            {label}
          </button>
        ))}
      </div>

      {format === "story" && (
        <div>
          {/* Slide navigator */}
          <div style={{ display: "flex", gap: 6, justifyContent: "center", marginBottom: 16 }}>
            {slideLabels.map((label, i) => (
              <button key={i} onClick={() => setActiveSlide(i)} style={{
                background: activeSlide === i ? "var(--border)" : "transparent",
                border: `1px solid ${activeSlide === i ? "#c0392b" : "var(--border)"}`,
                color: activeSlide === i ? "var(--text-heading)" : "var(--text-secondary)",
                padding: "4px 12px", borderRadius: 6, cursor: "pointer", fontSize: 11, fontFamily: "inherit",
              }}>
                {i + 1}. {label}
              </button>
            ))}
          </div>

          {/* Active slide */}
          <div style={{ display: "flex", justifyContent: "center", marginBottom: 16 }}>
            <div ref={slideRef}>
              {activeSlide === 0 && <StorySlideThesis customMessage={customMessage} />}
              {activeSlide === 1 && <StorySlideQuote match={match} type="soviet" />}
              {activeSlide === 2 && <StorySlideQuote match={match} type="modern" />}
              {activeSlide === 3 && <StorySlideExplanation match={match} tropeNames={tropeNames} />}
              {activeSlide === 4 && <StorySlideCTA sovietCorpusSize={sovietCorpusSize} modernCorpusSize={modernCorpusSize} />}
            </div>
          </div>

          {/* Share buttons */}
          <div style={{ display: "flex", gap: 8, justifyContent: "center", flexWrap: "wrap" }}>
            <button onClick={downloadStorySlide} disabled={exporting} style={{
              background: "linear-gradient(135deg, #833AB4, #E1306C, #F77737)",
              border: "none", color: "#fff", padding: "10px 20px", borderRadius: 8,
              cursor: exporting ? "wait" : "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit", opacity: exporting ? 0.6 : 1,
            }}>
              {exporting ? "Exporting..." : `Download Slide ${activeSlide + 1} for Instagram`}
            </button>
            <button onClick={downloadAllSlides} disabled={exporting} style={{
              background: "var(--bg-card-alt)", border: "1px solid var(--border)",
              color: "var(--text-secondary)", padding: "10px 20px", borderRadius: 8,
              cursor: exporting ? "wait" : "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit", opacity: exporting ? 0.6 : 1,
            }}>
              {exporting ? "Exporting..." : "Download All 5 Slides"}
            </button>
            {canWebShare && (
              <button onClick={webShareSlide} disabled={exporting} style={{
                background: "linear-gradient(135deg, #667eea, #764ba2)",
                border: "none", color: "#fff", padding: "10px 20px", borderRadius: 8,
                cursor: exporting ? "wait" : "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit", opacity: exporting ? 0.6 : 1,
              }}>
                {exporting ? "Sharing..." : "Share Slide..."}
              </button>
            )}
          </div>
        </div>
      )}

      {format === "thread" && (
        <div>
          <ThreadView match={match} tropeNames={tropeNames} sovietCorpusSize={sovietCorpusSize} modernCorpusSize={modernCorpusSize} customMessage={customMessage} />

          {/* Share buttons */}
          <div style={{ display: "flex", gap: 8, justifyContent: "center", marginTop: 20, flexWrap: "wrap" }}>
            <button onClick={shareToX} style={{
              background: "#000", border: "1px solid #2f3336", color: "#e7e9ea",
              padding: "10px 20px", borderRadius: 8, cursor: "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit",
              display: "flex", alignItems: "center", gap: 8,
            }}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor"><path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z"/></svg>
              Post First Tweet to X
            </button>
            <button onClick={copyThreadText} style={{
              background: "var(--bg-card-alt)", border: "1px solid var(--border)",
              color: "var(--text-secondary)", padding: "10px 20px", borderRadius: 8,
              cursor: "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit",
            }}>
              Copy Full Thread Text
            </button>
            {canWebShare && (
              <button onClick={webShareThread} style={{
                background: "linear-gradient(135deg, #667eea, #764ba2)",
                border: "none", color: "#fff", padding: "10px 20px", borderRadius: 8,
                cursor: "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit",
              }}>
                Share...
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

