// Custom component overrides for react-markdown, styled to match our theme
const MD_COMPONENTS = {
  h1: ({ children }) => (
    <h1 style={{ fontSize: 28, fontWeight: 800, color: "var(--text-heading)", marginBottom: 16, lineHeight: 1.3, background: "linear-gradient(90deg, #c0392b, #2980b9)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>{children}</h1>
  ),
  h2: ({ children }) => (
    <h2 style={{ fontSize: 22, fontWeight: 700, color: "var(--text-heading)", marginTop: 32, marginBottom: 12, lineHeight: 1.3 }}>{children}</h2>
  ),
  h3: ({ children }) => (
    <h3 style={{ fontSize: 17, fontWeight: 700, color: "var(--text-heading)", marginTop: 24, marginBottom: 8, lineHeight: 1.4 }}>{children}</h3>
  ),
  p: ({ children }) => (
    <p style={{ fontSize: 15, lineHeight: 1.8, color: "var(--text-secondary)", marginBottom: 16 }}>{children}</p>
  ),
  a: ({ href, children }) => (
    <a href={href} target="_blank" rel="noopener noreferrer" style={{ color: "#3498db", textDecoration: "underline" }}>{children}</a>
  ),
  blockquote: ({ children }) => (
    <blockquote style={{ borderLeft: "3px solid #c0392b", paddingLeft: 16, margin: "16px 0", color: "var(--text-primary)", fontStyle: "italic" }}>{children}</blockquote>
  ),
  code: ({ children }) => (
    <code style={{ background: "var(--bg-card-alt)", padding: "1px 4px", borderRadius: 3, fontSize: "0.9em" }}>{children}</code>
  ),
  hr: () => (
    <hr style={{ border: "none", borderTop: "1px solid var(--border)", margin: "32px 0" }} />
  ),
  table: ({ children }) => (
    <div style={{ overflowX: "auto", margin: "16px 0" }}>
      <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 13 }}>{children}</table>
    </div>
  ),
  th: ({ children }) => (
    <th style={{ textAlign: "left", padding: "8px 12px", borderBottom: "2px solid var(--border)", color: "var(--text-heading)", fontWeight: 700 }}>{children}</th>
  ),
  td: ({ children }) => (
    <td style={{ padding: "6px 12px", borderBottom: "1px solid var(--bg-card-alt)", color: "var(--text-secondary)", verticalAlign: "top" }}>{children}</td>
  ),
  ul: ({ children }) => (
    <ul style={{ paddingLeft: 24, marginBottom: 16, color: "var(--text-secondary)", fontSize: 15, lineHeight: 1.8 }}>{children}</ul>
  ),
  ol: ({ children }) => (
    <ol style={{ paddingLeft: 24, marginBottom: 16, color: "var(--text-secondary)", fontSize: 15, lineHeight: 1.8 }}>{children}</ol>
  ),
  li: ({ children }) => (
    <li style={{ marginBottom: 4 }}>{children}</li>
  ),
};

function MarkdownTab({ url, onNavigate, navigateLabel }) {
  const [content, setContent] = useState(null);

  useEffect(() => {
    fetch(url).then(r => r.text()).then(setContent).catch(() => setContent("Failed to load content."));
  }, [url]);

  if (!content) return <div style={{ color: "var(--text-secondary)", textAlign: "center", padding: 40 }}>Loading...</div>;

  return (
    <div style={{ maxWidth: 760, margin: "0 auto" }}>
      <ReactMarkdown remarkPlugins={[remarkGfm]} components={MD_COMPONENTS}>
        {content}
      </ReactMarkdown>
      {onNavigate && (
        <div style={{ textAlign: "center", margin: "32px 0" }}>
          <button onClick={onNavigate} style={{
            background: "linear-gradient(90deg, #c0392b, #2980b9)",
            border: "none", color: "#fff", padding: "12px 28px", borderRadius: 8,
            cursor: "pointer", fontSize: 14, fontWeight: 600, fontFamily: "inherit",
          }}>
            {navigateLabel}
          </button>
        </div>
      )}
    </div>
  );
}

// ============================================================
// EXPLORER TAB — browse passages and see top matches
// ============================================================

function ExplorerTab({ tropeNames, tropeColors }) {
  const [data, setData] = useState(null);
  const [corpus, setCorpus] = useState("soviet"); // "soviet" | "modern"
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch("/explorer_data.json")
      .then(r => { if (!r.ok) throw new Error("Not found"); return r.json(); })
      .then(setData)
      .catch(() => setError("Explorer data not yet generated. Run: python generate_explorer_data.py"));
  }, []);

  if (error) return (
    <div style={{ textAlign: "center", padding: 40 }}>
      <div style={{ fontSize: 14, color: "var(--text-secondary)", marginBottom: 12 }}>{error}</div>
      <code style={{ fontSize: 12, color: "var(--text-muted)", background: "var(--bg-card-alt)", padding: "8px 16px", borderRadius: 6 }}>
        python generate_explorer_data.py
      </code>
    </div>
  );
  if (!data) return <div style={{ color: "var(--text-secondary)", textAlign: "center", padding: 40 }}>Loading explorer data...</div>;

  const passages = corpus === "soviet" ? data.soviet_passages : data.modern_passages;
  const selected = passages[selectedIdx];
  if (!selected) return null;

  const isSoviet = corpus === "soviet";
  const accentColor = isSoviet ? "#c0392b" : "#3498db";
  const matchColor = isSoviet ? "#3498db" : "#c0392b";

  return (
    <div>
      <div style={{ fontSize: 12, color: "var(--text-secondary)", marginBottom: 16 }}>
        Select a passage to explore its closest matches from the {isSoviet ? "modern" : "Soviet"} corpus
      </div>

      {/* Corpus toggle */}
      <div style={{ display: "flex", gap: 8, justifyContent: "center", marginBottom: 20 }}>
        {[["soviet", "Soviet Passages", "#c0392b"], ["modern", "Modern Passages", "#3498db"]].map(([key, label, color]) => (
          <button key={key} onClick={() => { setCorpus(key); setSelectedIdx(0); }} style={{
            background: corpus === key ? color : "var(--bg-card-alt)",
            border: `1px solid ${corpus === key ? color : "var(--border)"}`,
            color: corpus === key ? "#fff" : "var(--text-secondary)",
            padding: "8px 20px", borderRadius: 8, cursor: "pointer", fontSize: 13, fontWeight: 600, fontFamily: "inherit",
          }}>
            {label} ({(key === "soviet" ? data.soviet_passages : data.modern_passages).length})
          </button>
        ))}
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "1fr 1.5fr", gap: 20, alignItems: "start" }}>
        {/* Left: passage list */}
        <div style={{ maxHeight: 600, overflowY: "auto", border: "1px solid var(--border)", borderRadius: 8 }}>
          {passages.map((p, i) => (
            <div key={p.id} onClick={() => setSelectedIdx(i)} style={{
              padding: "10px 12px", cursor: "pointer", borderBottom: "1px solid var(--bg-card-alt)",
              background: selectedIdx === i ? `${accentColor}15` : "transparent",
              borderLeft: selectedIdx === i ? `3px solid ${accentColor}` : "3px solid transparent",
            }}>
              <div style={{ fontSize: 12, color: "var(--text-primary)", lineHeight: 1.4 }}>
                {p.text.slice(0, 100)}{p.text.length > 100 ? "..." : ""}
              </div>
              <div style={{ fontSize: 10, color: "var(--text-muted)", marginTop: 4 }}>
                {p.source} — {p.year}
              </div>
            </div>
          ))}
        </div>

        {/* Right: selected passage + matches */}
        <div>
          {/* Selected passage */}
          <div style={{ background: "var(--bg-card)", border: `1px solid ${accentColor}44`, borderRadius: 12, padding: 20, marginBottom: 16 }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: accentColor, letterSpacing: 2, textTransform: "uppercase", marginBottom: 8 }}>
              {isSoviet ? "SOVIET PASSAGE" : "MODERN TEXT"} — {selected.year}
            </div>
            <div style={{ fontSize: 15, lineHeight: 1.6, color: "var(--text-primary)", borderLeft: `3px solid ${accentColor}`, paddingLeft: 14, marginBottom: 12 }}>
              "{selected.text}"
            </div>
            <div style={{ fontSize: 11, color: "var(--text-muted)" }}>{selected.source}</div>
            {selected.tropes && selected.tropes.length > 0 && (
              <div style={{ display: "flex", gap: 4, marginTop: 8, flexWrap: "wrap" }}>
                {selected.tropes.map(t => (
                  <span key={t} style={{
                    background: (tropeColors[t] || "#888") + "22",
                    border: `1px solid ${(tropeColors[t] || "#888")}55`,
                    color: tropeColors[t] || "#888",
                    padding: "2px 6px", borderRadius: 4, fontSize: 9, fontWeight: 600,
                  }}>
                    {tropeNames[t] || t}
                  </span>
                ))}
              </div>
            )}
          </div>

          {/* Top matches */}
          <div style={{ fontSize: 11, color: "var(--text-secondary)", marginBottom: 8, fontWeight: 600, letterSpacing: 1, textTransform: "uppercase" }}>
            Top {selected.top_matches?.length || 0} matches from {isSoviet ? "modern" : "Soviet"} corpus
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {(selected.top_matches || []).map((match, mi) => {
              const pct = Math.round(match.similarity * 100);
              return (
                <div key={mi} style={{
                  background: "var(--bg-card)", border: "1px solid var(--border)", borderRadius: 8,
                  padding: "12px 14px", position: "relative", overflow: "hidden",
                }}>
                  {/* Similarity bar background */}
                  <div style={{
                    position: "absolute", left: 0, top: 0, bottom: 0,
                    width: `${pct}%`, background: `${matchColor}08`,
                  }} />
                  <div style={{ position: "relative" }}>
                    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                      <span style={{ fontSize: 10, fontWeight: 700, color: matchColor, letterSpacing: 1 }}>
                        #{mi + 1} — {match.year}
                      </span>
                      <span style={{ fontSize: 11, fontWeight: 700, color: pct >= 75 ? "#e74c3c" : pct >= 60 ? "#f39c12" : "var(--text-muted)" }}>
                        {pct}%
                      </span>
                    </div>
                    <div style={{ fontSize: 13, lineHeight: 1.5, color: "var(--text-primary)" }}>
                      "{match.text}"
                    </div>
                    <div style={{ fontSize: 10, color: "var(--text-muted)", marginTop: 4 }}>{match.source}</div>
                    {match.tropes && match.tropes.length > 0 && (
                      <div style={{ display: "flex", gap: 3, marginTop: 6, flexWrap: "wrap" }}>
                        {match.tropes.map(t => (
                          <span key={t} style={{
                            background: (tropeColors[t] || "#888") + "18",
                            color: tropeColors[t] || "#888",
                            padding: "1px 5px", borderRadius: 3, fontSize: 8, fontWeight: 600,
                          }}>
                            {tropeNames[t] || t}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

